begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values ('10000000-0000-4000-8000-000000000001','obligation-a@example.test'),('10000000-0000-4000-8000-000000000002','obligation-b@example.test');
insert into auth.sessions(id,user_id) values ('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001'),('20000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002');
insert into finance.profiles(id,display_name) values ('10000000-0000-4000-8000-000000000001','Synthetic A'),('10000000-0000-4000-8000-000000000002','Synthetic B');
insert into finance.households(id,name) values ('30000000-0000-4000-8000-000000000001','Synthetic A'),('30000000-0000-4000-8000-000000000002','Synthetic B');
insert into finance.household_members(id,household_id,user_id,display_name) values ('40000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Synthetic A'),('40000000-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002','Synthetic B');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","session_id":"20000000-0000-4000-8000-000000000001"}',true);
select is(api.create_account('{"account":{"id":"70000000-0000-4000-8000-000000000001","householdId":"30000000-0000-4000-8000-000000000001","name":"Synthetic","ownership":{"kind":"HOUSEHOLD"},"type":"BANK","currency":"ILS","valuationCurrency":"ILS","balancePolicy":"LEDGER","status":"ACTIVE"},"version":1,"manualSourceId":"80000000-0000-4000-8000-000000000001"}'::jsonb)->>'ok','true','synthetic account');
create function pg_temp.command() returns jsonb language sql as $$select '{"id":"50000000-0000-4000-8000-000000000001","householdId":"30000000-0000-4000-8000-000000000001","action":"CONFIRM","expectedVersion":0,"idempotencyKey":"synthetic-obligation-command","acknowledge":true,"effectiveFrom":"2026-10-01","origin":[],"plan":{"name":"Synthetic","accountId":"70000000-0000-4000-8000-000000000001","ownership":{"kind":"HOUSEHOLD"},"money":{"amount":"10","currency":"ILS"},"effect":"EXPENSE","schedule":{"frequency":"MONTHLY","day":31},"startDate":"2026-10-01","endDate":null}}'::jsonb$$;
select ok(not has_function_privilege('anon','api.obligation_command(jsonb)','EXECUTE'),'anonymous command denied');
select ok(not has_function_privilege('anon','api.obligations_snapshot()','EXECUTE'),'anonymous snapshot denied');
select ok(not has_function_privilege('authenticated','private.obligation_evidence(uuid,jsonb)','EXECUTE'),'internal evidence validator hidden');
select ok(not has_function_privilege('authenticated','private.obligation_plan_valid(jsonb)','EXECUTE'),'internal plan validator hidden');
select ok(not has_table_privilege('authenticated','finance.obligations','INSERT'),'no direct creation');
select ok(not has_table_privilege('authenticated','finance.obligation_revisions','UPDATE'),'no revision mutation');
select ok(not has_table_privilege('authenticated','finance.obligation_payment_claims','DELETE'),'no claim stealing');
select ok(not has_table_privilege('authenticated','private.obligation_receipts','SELECT'),'private receipts hidden');
select ok(not has_table_privilege('authenticated','private.obligation_audit','SELECT'),'private audit hidden');
select ok(not prosecdef and provolatile='s','stable invoker snapshot') from pg_proc where oid='api.obligations_snapshot()'::regprocedure;
select is((select proconfig[1] from pg_proc where oid='private.obligation_command(jsonb)'::regprocedure),'search_path=""','empty command search path');
set local role anon;
select throws_ok('select api.obligations_snapshot()','42501',null,'anonymous read call');
set local role authenticated;
select set_config('request.jwt.claims','{}',true);
select is(api.obligation_command(pg_temp.command())->'error'->>'code','NOT_AUTHORIZED','missing live session');
select is(api.obligations_snapshot()->'error'->>'code','NOT_AUTHORIZED','missing session read');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","session_id":"20000000-0000-4000-8000-000000000001"}',true);
select is(api.obligation_command(pg_temp.command())->>'version','1','explicit manual confirmation');
select is(api.obligation_command(pg_temp.command())->>'version','1','exact retry');
select is(api.obligation_command(jsonb_set(pg_temp.command(),'{plan,money,amount}','"11"'))->'error'->>'code','CONFLICT','complete-payload receipt digest');
select is(api.obligation_command(pg_temp.command()||'{"acknowledge":false,"idempotencyKey":"synthetic-unacknowledged"}')->'error'->>'code','INVALID_INPUT','no implicit confirmation');
select is(api.obligation_command(jsonb_set(pg_temp.command()||'{"idempotencyKey":"synthetic-null-effect"}','{plan,effect}','null'))->'error'->>'code','INVALID_INPUT','null effect cannot bypass validator');
select is(api.obligation_command(pg_temp.command()||'{"householdId":"30000000-0000-4000-8000-000000000002"}')->'error'->>'code','NOT_AUTHORIZED','foreign household denied');
select is(api.obligation_command(jsonb_set(pg_temp.command()||'{"id":"50000000-0000-4000-8000-000000000003","idempotencyKey":"synthetic-foreign-member"}','{plan,ownership}','{"kind":"MEMBER","memberId":"40000000-0000-4000-8000-000000000002"}'))->'error'->>'code','INVALID_INPUT','forged member denied');
select is(api.obligation_command(pg_temp.command()||'{"action":"EDIT","expectedVersion":1,"effectiveFrom":"2026-11-01","idempotencyKey":"synthetic-obligation-edit"}')->>'version','2','edit appends history');
select is(api.obligation_command(pg_temp.command()||'{"action":"EDIT","expectedVersion":1,"effectiveFrom":"2026-12-01","idempotencyKey":"synthetic-obligation-stale"}')->'error'->>'code','CONFLICT','stale version denied');
select is(api.obligation_command(pg_temp.command()||'{"action":"EDIT","expectedVersion":2,"effectiveFrom":"2026-10-01","idempotencyKey":"synthetic-obligation-retro"}')->'error'->>'code','INVALID_INPUT','retroactive schedule replacement denied');
select is(api.obligation_command(pg_temp.command()||'{"action":"ARCHIVE","expectedVersion":2,"effectiveFrom":"2026-12-01","idempotencyKey":"synthetic-obligation-archive"}')->>'version','3','archive version');
select is((select count(*) from finance.obligation_revisions),3::bigint,'immutable history retained');
select is(api.obligations_snapshot()->'snapshot'->>'size','3','snapshot explicit size');
select throws_ok('update finance.obligations set version=99','42501',null,'direct head mutation denied');
select throws_ok('delete from finance.obligation_revisions','42501',null,'direct history delete denied');
select throws_ok('select private.obligation_evidence(null,null)','42501',null,'indirect evidence oracle denied');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","role":"authenticated","session_id":"20000000-0000-4000-8000-000000000002"}',true);
select is((select count(*) from finance.obligation_revisions),0::bigint,'two-household isolation');
select is(jsonb_array_length(api.obligations_snapshot()->'snapshot'->'revisions'),0,'invoker snapshot isolation');
reset role;
select throws_ok('update finance.obligation_revisions set body=body','23514',null,'immutable privileged update');
select is((select count(*) from private.obligation_receipts),3::bigint,'atomic receipt per decision');
select is((select count(*) from private.obligation_audit),3::bigint,'minimal audit per decision');
select throws_ok($$insert into finance.obligations values('30000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000099','70000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000002','ILS',1,'ACTIVE')$$,'23503',null,'restrictive household/member FK');
select throws_ok($$insert into finance.obligation_origins values('30000000-0000-4000-8000-000000000002','50000000-0000-4000-8000-000000000001',null,'70000000-0000-4000-8000-000000000001',gen_random_uuid(),gen_random_uuid(),gen_random_uuid())$$,'23503',null,'restrictive household/origin FK');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","session_id":"20000000-0000-4000-8000-000000000001"}',true);
savepoint bounds;
insert into finance.obligation_revisions(household_id,id,version,actor_member_id,effective_from,body)
select household_id,id,v,actor_member_id,effective_from,body||jsonb_build_object('version',v) from finance.obligation_revisions cross join generate_series(4,10004) v where version=1;
set local role authenticated;
select is(api.obligations_snapshot()->'error'->>'code','INVALID_INPUT','bounded decision collection');
select ok(not api.obligations_snapshot()?'snapshot','no truncated success');
reset role;
rollback to bounds;
savepoint bytes;
insert into finance.obligation_revisions(household_id,id,version,actor_member_id,effective_from,body)
select household_id,id,v,actor_member_id,effective_from,body||jsonb_build_object('version',v,'syntheticPadding',repeat('s',2000)) from finance.obligation_revisions cross join generate_series(4,9003) v where version=1;
set local role authenticated;
select is(api.reporting_snapshot()->>'ok','true','nested financial report below byte bound');
select is(api.obligations_snapshot()->'error'->>'code','INVALID_INPUT','combined 16 MiB bound');
select ok(not api.obligations_snapshot()?'snapshot','no partial bytes response');
reset role;
rollback to bytes;
update finance.household_members set status='REVOKED' where id='40000000-0000-4000-8000-000000000001';
set local role authenticated;
select is(api.obligation_command(pg_temp.command())->'error'->>'code','NOT_AUTHORIZED','unchanged revoked JWT replay denied');
select is(jsonb_array_length(api.obligations_snapshot()->'snapshot'->'revisions'),0,'revocation clears history');
reset role;
delete from auth.sessions where id='20000000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","role":"authenticated","session_id":"20000000-0000-4000-8000-000000000002"}',true);
select is(api.obligations_snapshot()->'error'->>'code','NOT_AUTHORIZED','deleted session read denied');
reset role;
delete from auth.users where id='10000000-0000-4000-8000-000000000001';
select is((select count(*) from finance.obligation_revisions),3::bigint,'deleted author retained');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","session_id":"20000000-0000-4000-8000-000000000001"}',true);
select is(api.obligation_command(pg_temp.command())->'error'->>'code','NOT_AUTHORIZED','deleted user replay denied');
select * from finish();
rollback;
